    /// <summary>
    /// Event names the subscription listens for
    /// </summary>
    [JsonPropertyName("event_types")]
    public IReadOnlyList<string>? EventTypes { get; init; }

    /// <summary>
    /// Filters that scope which resources are delivered
    /// </summary>
    [JsonPropertyName("resource_filters")]
    public JsonElement? ResourceFilters { get; init; }

    /// <summary>
    /// Destination URL where webhook payloads are sent
    /// </summary>
    [JsonPropertyName("url")]
    public string? Url { get; init; }

    /// <summary>
    /// Extra HTTP headers sent with each webhook request
    /// </summary>
    [JsonPropertyName("custom_headers")]
    public JsonElement? CustomHeaders { get; init; }

    /// <summary>
    /// Hours between snapshot deliveries
    /// </summary>
    [JsonPropertyName("interval_hours")]
    public long? IntervalHours { get; init; }

    /// <summary>
    /// Maximum number of items per delivery
    /// </summary>
    [JsonPropertyName("max_items")]
    public long? MaxItems { get; init; }

    /// <summary>
    /// Type of signing secret to attach to the subscription
    /// </summary>
    [JsonPropertyName("secret_type")]
    public string? SecretType { get; init; }

}

/// <summary>
/// A subscription just created, with the signing secret attached. The secret is shown
/// on this response only and never again.
/// </summary>
public sealed record WebhookSubscriptionCreated(
    [property: JsonPropertyName("id")] string Id,
    [property: JsonPropertyName("kind")] string Kind,
    [property: JsonPropertyName("resource")] string Resource,
    [property: JsonPropertyName("event_types")] IReadOnlyList<string> EventTypes,
    [property: JsonPropertyName("resource_filters")] JsonElement ResourceFilters,
    [property: JsonPropertyName("url")] string Url,
    [property: JsonPropertyName("custom_headers")] JsonElement CustomHeaders,
    [property: JsonPropertyName("interval_hours")] long? IntervalHours,
    [property: JsonPropertyName("max_items")] long? MaxItems,
    [property: JsonPropertyName("secret_prefix")] string SecretPrefix,
    [property: JsonPropertyName("secret")] string? Secret,
    [property: JsonPropertyName("enabled")] bool Enabled,
    [property: JsonPropertyName("created")] DateTimeOffset Created
);
